="table-wrapper"><table class="data-table skill-assignments-table"><thead><tr><th>Freelancer</th><th>Skill</th><th>Proficiency</th><th>Actions</th></tr></thead><tbody><?php if($assignments&&$assignments->num_rows>0): while($row=$assignments->fetch_assoc()):?><tr><td class="col-name"><?php echo htmlspecialchars($row['freelancer_name']); ?> (ID: <?php echo $row['freelancer_id']; ?>)</td><td class="col-name"><?php echo htmlspecialchars($row['skill_name']); ?></td><td class="col-status"><span class="badge badge-<?php echo strtolower($row['proficiency_level']); ?>"><?php echo htmlspecialchars($row['proficiency_level']); ?></span></td><td class="col-actions"><a class="btn btn-sm btn-danger" href="<?php echo $basePath; ?>/pages/delete_freelancer_skill.php?fid=<?php echo $row['freelancer_id']; ?>&sid=<?php echo $row['skill_id']; ?>" onclick="return confirm('Remove this skill assignment?');">Remove</a></td></tr><?php endwhile; else:?><tr><td colspan="4"><div class="empty-state"><p>No skill assignments found.</p></div></td></tr><?php endif;?></tbody></table></div></section></div><?php include __DIR__ . '/../includes/footer.php'; $conn->close(); ?>
